// Settings → About → Open-source licences: every third-party component in the
// app and in the unit's firmware, with its licence. The unit has no screen of
// its own for the notices its libraries ask to show, so they are here too.
// The list is generated by scripts/gen-licences.mjs.

import { router } from 'expo-router';
import * as WebBrowser from 'expo-web-browser';
import { useMemo, useState } from 'react';
import { Platform, Pressable, SectionList, TextInput, View } from 'react-native';

import { Card, T, Title } from '@/components/ui';
import licences from '@/data/licences.json';
import { useTheme } from '@/theme';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

interface Item {
  name: string;
  version: string;
  licence: string;
  url: string | null;
  text: number;
}

const SOURCE_URL = 'https://github.com/OxMarco/Quiesco';
const MONO = Platform.select({ ios: 'Menlo', default: 'monospace' });

export default function LicencesScreen() {
  const t = useTheme();
  const insets = useSafeAreaInsets();
  const [query, setQuery] = useState('');
  const [open, setOpen] = useState<string | null>(null);

  const sections = useMemo(() => {
    const q = query.trim().toLowerCase();
    return licences.sections
      .map((s) => ({
        title: s.title,
        data: (s.items as Item[]).filter((i) => !q || i.name.toLowerCase().includes(q) || i.licence.toLowerCase().includes(q)),
      }))
      .filter((s) => s.data.length > 0);
  }, [query]);

  return (
    // Padded in JS, not SafeAreaView, so the list's end is not left below the screen (see Screen).
    <View className="flex-1 bg-bg" style={{ paddingTop: insets.top }}>
      <SectionList
        sections={sections}
        keyExtractor={(i, index) => `${i.name}@${i.version}#${index}`}
        contentContainerClassName="px-4"
        contentContainerStyle={{ paddingBottom: insets.bottom + 16 }}
        keyboardShouldPersistTaps="handled"
        stickySectionHeadersEnabled={false}
        initialNumToRender={30}
        ListHeaderComponent={
          <View className="gap-4 pb-2">
            <Pressable
              onPress={() => (router.canGoBack() ? router.back() : router.replace('/unit'))}
              accessibilityRole="button"
              accessibilityLabel="Back to Settings"
              hitSlop={12}
              className="self-start pt-3 active:opacity-60">
              <T className="text-primary text-base">‹ Settings</T>
            </Pressable>
            <Title>Open-source licences</Title>
            <Card className="gap-2">
              <T className="text-sm leading-5">
                Quiesco’s app and firmware are free software under the GNU General Public License v3.0. The complete source,
                including how to rebuild the firmware, is on GitHub.
              </T>
              <Pressable onPress={() => void WebBrowser.openBrowserAsync(SOURCE_URL).catch(() => {})} accessibilityRole="link" hitSlop={8}>
                <T className="text-primary text-sm font-body-semi">github.com/OxMarco/Quiesco</T>
              </Pressable>
            </Card>
            <T className="text-[13px] text-muted leading-[18px] px-1">
              Quiesco is built on the work below. Tap a component for its licence.
            </T>
            <TextInput
              value={query}
              onChangeText={setQuery}
              placeholder="Search by name or licence"
              placeholderTextColor={t.textMuted}
              autoCorrect={false}
              autoCapitalize="none"
              clearButtonMode="while-editing"
              accessibilityLabel="Search licences"
              selectionColor={t.primary}
              className="h-11 rounded-xl bg-surface px-3.5 font-body text-[15px] text-ink"
            />
          </View>
        }
        renderSectionHeader={({ section }) => (
          <T className="font-body-semi text-muted text-xs uppercase tracking-widest mt-5 mb-2 px-1">
            {section.title} · {section.data.length}
          </T>
        )}
        renderItem={({ item }) => {
          const key = `${item.name}@${item.version}`;
          const expanded = open === key;
          return (
            <View className="border-b border-line">
              <Pressable
                onPress={() => setOpen(expanded ? null : key)}
                accessibilityRole="button"
                accessibilityState={{ expanded }}
                className="flex-row items-center justify-between gap-3 py-3 px-1 active:opacity-60">
                <View className="flex-1 gap-0.5">
                  <T className="text-[15px]" numberOfLines={1}>
                    {item.name}
                  </T>
                  <T className="text-[13px] text-muted" numberOfLines={1}>
                    {item.version} · {item.licence}
                  </T>
                </View>
                <T className="text-muted text-lg">{expanded ? '−' : '+'}</T>
              </Pressable>
              {expanded && (
                <View className="pb-3 px-1 gap-2">
                  {item.url && (
                    <Pressable onPress={() => void WebBrowser.openBrowserAsync(item.url!).catch(() => {})} accessibilityRole="link" hitSlop={6}>
                      <T className="text-primary text-[13px]" numberOfLines={1}>
                        {item.url}
                      </T>
                    </Pressable>
                  )}
                  <T selectable className="text-[11px] leading-4 text-muted" style={{ fontFamily: MONO }}>
                    {licences.texts[item.text]}
                  </T>
                </View>
              )}
            </View>
          );
        }}
        ListEmptyComponent={<T className="text-muted px-1 py-6">Nothing matches “{query}”.</T>}
      />
    </View>
  );
}
